import axios from "axios";
import React, { useState, useEffect } from "react";

const Slider = ({ setIndicator }) => {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [slides, setSlides] = useState([]);

  useEffect(() => {
    setIndicator(true);
    const fetchSlides = async () => {
      try {
        const response = await axios.get("http://localhost:5000/images");
        const sliderImages =
          response.data?.[0]?.slider?.filter((ele) => ele.isActive === true) ?? [];
        setSlides(sliderImages);
      } catch (error) {
        console.error("Error fetching images section content:", error);
      } finally {
        setIndicator(false);
      }
    };
    fetchSlides();
  }, []);

  useEffect(() => {
    if (slides.length > 0) {
      const timer = setTimeout(() => {
        goToNext();
      }, 5000); // Auto-slide every 5 seconds
      return () => clearTimeout(timer);
    }
  }, [currentIndex, slides.length]);

  const goToPrevious = () => {
    setCurrentIndex((prevIndex) => (prevIndex - 1 + slides.length) % slides.length);
  };

  const goToNext = () => {
    setCurrentIndex((prevIndex) => (prevIndex + 1) % slides.length);
  };

  const goToSlide = (slideIndex) => {
    setCurrentIndex(slideIndex);
  };

  return (
    <div className="slider">
      {slides.length > 0 ? (
        <>
          <div onClick={goToPrevious} className="arrow left">❰</div>
          <div onClick={goToNext} className="arrow right">❱</div>

          <div className="slider-container">
            <div
              className="slide-track"
              style={{ transform: `translateX(-${currentIndex * 100}%)` }}
            >
              {slides.map((slide, index) => (
                <img key={index} className="slide" src={slide.url} alt={`Slide ${index + 1}`} />
              ))}
            </div>
          </div>

          <div className="dots">
            {slides.map((_, slideIndex) => (
              <div
                key={slideIndex}
                className={`dot ${slideIndex === currentIndex ? "active" : ""}`}
                onClick={() => goToSlide(slideIndex)}
              >
                ●
              </div>
            ))}
          </div>
        </>
      ) : (
        <p style={{ textAlign: "center", color: "red" }}>No active slides available</p>
      )}
    </div>
  );
};

export default Slider;
